import sys

def solve():
    s = sys.stdin.readline().strip()
    t = sys.stdin.readline().strip()

    n = len(s)
    m = len(t)

    if m > n:
        print(0)
        return

    dp = [0] * (n + 1)

    for i in range(n):
        if i < m - 1:
            dp[i+1] = dp[i]
            continue

        max_prev = dp[i - m + 1]

        can_place = True
        for k in range(m):
            char_s = s[i - m + 1 + k]
            char_t = t[k]
            if char_s != '?' and char_s != char_t:
                can_place = False
                break

        if can_place:
            current_val = dp[i - m + 1] + 1
            if current_val > max_prev:
                max_prev = current_val

        dp[i+1] = max_prev

    print(dp[n])

if __name__ == "__main__":
    solve()
